effect.shader:
#define PI 3.14159265359

mat2 rot2m(float a) { 
    float s = sin(a); 
    float c = cos(a); 
    return mat2(c, -s, s, c); 
}

mat3 rotX(float a) { float s = sin(a); float c = cos(a); return mat3(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c); }
mat3 rotY(float a) { float s = sin(a); float c = cos(a); return mat3(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c); }
mat3 rotZ(float a) { float s = sin(a); float c = cos(a); return mat3(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0); }

float Star(vec2 uv, float a, float sparkle, bool glowOn) {
    vec2 av1 = abs(uv);
    vec2 av2 = abs(uv * rot2m(a));
    float star = max(av1.x * av1.y, av2.x * av2.y);
    star = max(0.0, 1.0 - star * (glowOn ? 1e3 : 3e3));
    float d = length(uv);
    float m = glowOn ? min(5.0, 1e-2 / (d + 0.0001)) : smoothstep(0.2, 0.0, d);
    return m + pow(star, glowOn ? 4.0 : 2.0) * sparkle;
}

float Hash21(vec2 p) {
    p = fract(p * vec2(123.34, 145.54));
    p += dot(p, p + 45.23);
    return fract(p.x * p.y);
}

vec3 getStarColor(float index) {
    int idx = int(mod(index * 5.0, 5.0));
    if (idx == 0) return color1.rgb;
    if (idx == 1) return color2.rgb;
    if (idx == 2) return color3.rgb;
    if (idx == 3) return color4.rgb;
    return color5.rgb;
}

vec3 StarLayer(vec2 uv, vec2 progOffset, float t, float sparkle, mat3 camMat, bool glowOn) {
    vec2 shiftedUV = uv + progOffset;
    vec2 gv = fract(shiftedUV) - 0.5;
    vec2 id = floor(shiftedUV);
    vec3 col = vec3(0.0);

    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 offs = vec2(float(x), float(y));
            float n = Hash21(id - offs);
            vec3 N = fract(n * vec3(10.0, 100.0, 1000.0));
            vec2 p = (N.xy - 0.5) * 0.7;

            vec3 starPos3D = vec3(gv - p + offs, 0.0);
            starPos3D = camMat * starPos3D;

            float brightness = Star(starPos3D.xy, n * 6.2831 + (t + xxg), sparkle, glowOn);

            vec3 baseCol = getStarColor(n);
            vec3 star = brightness * baseCol * N.z * N.z;

            star *= 1.0 + sin(((t + xxh) + n) * 20.0) * smoothstep(sin(t) * 0.5 + 0.5, 1.0, fract(10.0 * n));

            float d = length(gv + offs);
            col += star * smoothstep(1.5, 0.8, d);
        }
    }
    return col;
}

void main() {
    vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm);
    if (texColor.a <= 0.0001) {
        gl_FragColor = vec4(0.0);
        return;
    }

    vec2 TanRyu = ((vec2(acScreenNorm.x, 1.0 - acScreenNorm.y) * acScreenSize) - acLayerCenter) / acLayerSize;
    TanRyu.y *= acLayerSize.y / acLayerSize.x;
    TanRyu /= scale;
    TanRyu *= rot2m((0.0 + angle) * 0.0174533);
    TanRyu += vec2((0.0 + position.x), (0.0 + position.y)) * vec2(-1.0, 1.0) / 500.0;
    TanRyu /= vec2(scale * stretch.x, scale * stretch.y);

    float rx = (SPLITXYZ ? ROT2 : 0.0) * PI / 180.0;
    float ry = (SPLITXYZ ? ROT3 : 0.0) * PI / 180.0;
    float rz = (SPLITXYZ ? ROT4 : 0.0) * PI / 180.0;
    mat3 camMatrix = rotZ(rz) * rotY(ry) * rotX(rx);

    float masterT = autop ? (rrr ? PROGRESS * 0.1 - (acTime * 0.5) : PROGRESS * 0.1 + (acTime * 0.5)) : PROGRESS * 0.1;

    vec2 progOffset = vec2(0.0);
    float zProgressMod = 0.0;

    if (SPLIT_PROG) {
        progOffset = vec2(PROGRESS_X * 0.05, PROGRESS_Y * 0.05);
        zProgressMod = PROGRESS_Z * 0.05;
    }

    float t = masterT + zProgressMod;

    if (autor) { 
        TanRyu *= rot2m(-t * 0.2); 
    }

    vec3 col = vec3(0.0);
    float speed = 0.2;
    int maxLayers = int(clamp(NUM_LAYERS, 1.0, 25.0));
    float stepVal = 1.0 / float(maxLayers);

    for (int i = 0; i < 25; i++) {
        if (float(i) >= float(maxLayers)) break;
        float fi = float(i) * stepVal;
        float lt = autos ? fract(t * speed + fi) : fract(0.5 * speed + fi);
        float sc = mix(10.0, 0.25, lt);
        float fade = smoothstep(0.0, 0.4, lt) * smoothstep(1.0, 0.95, lt);
        vec2 sv = TanRyu * sc + fi * 134.53;
        col += StarLayer(sv, progOffset, t, fade, camMatrix, enableGlow) * fade;
    }

    col *= (enableGlow ? 4.0 : 2.5);

    vec4 fragColor = vec4(col, 1.0);
    vec4 factor = mix(vec4(0.0, 0.0, 0.0, 1.0) * texColor.a, fragColor, 1.0);
    vec4 resultfinal;

    if (blendMode == 0) {
        resultfinal = (factor * hardness) * texColor.a;
    } else if (blendMode == 1) {
        factor *= hardness;
        vec4 c = factor + vec4(1.0) * (1.0 - factor.a);
        resultfinal = vec4((texColor.rgb / max(texColor.a, 0.001)) * c.rgb, 1.0) * texColor.a;
    } else if (blendMode == 2) {
        factor *= hardness;
        resultfinal = vec4(1.0 - ((1.0 - (texColor.rgb / max(texColor.a, 0.001))) * (1.0 - factor.rgb)), 1.0) * texColor.a;
    } else {
        factor *= hardness;
        resultfinal = (factor * hardness) * texColor.a;
    }

    gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
}
